package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

/** Exercise the production corner windows and their ordering above a native editor. */
public final class NotebookEditorCornersTest {
    public static void main(String[] args) throws Exception {
        String source = new String(Files.readAllBytes(Paths.get(
            "app/src/main/java/org/eink/inkprobe/notebook/NotebookEditorCorners.java")), StandardCharsets.UTF_8);
        String implementation = source.substring(source.indexOf("final class NotebookEditorCorners"))
            .replaceFirst("final class NotebookEditorCorners", "static final class NotebookEditorCorners");
        String fixture = String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;",
            "public class EditorCornersFixture {",
            "static final List<String> events=new ArrayList<>();static long order;",
            "static class Context{Resources getResources(){return new Resources();}}static class Resources{Metrics getDisplayMetrics(){return new Metrics();}}static class Metrics{float density=1;}",
            "static class Rect{int left,top,right,bottom;Rect(){}Rect(Rect r){set(r.left,r.top,r.right,r.bottom);}void set(int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;}void setEmpty(){set(0,0,0,0);}boolean isEmpty(){return left>=right||top>=bottom;}int width(){return right-left;}int height(){return bottom-top;}public boolean equals(Object x){if(!(x instanceof Rect))return false;Rect r=(Rect)x;return left==r.left&&top==r.top&&right==r.right&&bottom==r.bottom;}}",
            "static class Gravity{static final int TOP=48,LEFT=3;}static class WindowManager{static class LayoutParams{static final int TYPE_APPLICATION_PANEL=1000,TYPE_APPLICATION_SUB_PANEL=1002;}}",
            "static class View{static final int VISIBLE=0,GONE=8;interface Click{void click(View v);}Click click;Object layout;int visibility;String name;void setOnClickListener(Click c){click=c;}void performClick(){if(click!=null)click.click(this);}void setContentDescription(String s){name=s;}void setVisibility(int v){visibility=v;}Object getLayoutParams(){return layout;}void setLayoutParams(Object p){layout=p;}}",
            "static class FrameLayout extends View{}static class LinearLayout extends View{static final int HORIZONTAL=0;LinearLayout(Context c){}void setOrientation(int i){}void addView(View v,LayoutParams p){v.layout=p;}static class LayoutParams{int width,height,leftMargin;LayoutParams(int w,int h){width=w;height=h;}}}",
            "static class NotebookIconDrawable{enum Icon{VIEW_BACK,VIEW_FORWARD}}static class NotebookIconButton extends View{NotebookIconButton(Context c,NotebookIconDrawable.Icon i,String d){name=d;}}",
            "static class NotebookWindowControls{interface Listener{void menu();void minimize();}final NotebookIconButton menu,minimize;NotebookWindowControls(Context c,FrameLayout r,FrameLayout b,NotebookWorkspace w,NotebookWorkspace.Pane p,Listener l,String n,boolean embedded){if(!embedded)throw new AssertionError(\"overlay controls must not be embedded in the surface window\");menu=new NotebookIconButton(c,NotebookIconDrawable.Icon.VIEW_BACK,\"menu\");minimize=new NotebookIconButton(c,NotebookIconDrawable.Icon.VIEW_FORWARD,\"minimize\");menu.setOnClickListener(v->l.menu());minimize.setOnClickListener(v->l.minimize());}}",
            "static class PopupWindow{static final int INPUT_METHOD_NEEDED=1;final View content;int width,height,x,y,layer,updates;long shownOrder;boolean showing;PopupWindow(View v,int w,int h,boolean f){content=v;width=w;height=h;}void setTouchable(boolean b){}void setOutsideTouchable(boolean b){}void setFocusable(boolean b){}void setInputMethodMode(int n){}void setClippingEnabled(boolean b){}void setIsLaidOutInScreen(boolean b){}void setAnimationStyle(int n){}void setElevation(int n){}void setEnterTransition(Object o){}void setExitTransition(Object o){}void setWindowLayoutType(int n){layer=n;}void setWidth(int n){width=n;}void setHeight(int n){height=n;}boolean isShowing(){return showing;}void dismiss(){showing=false;}void update(int x,int y,int w,int h){this.x=x;this.y=y;width=w;height=h;updates++;}}",
            "static class NotebookPopupHost{static int attempts,failAt;static boolean show(PopupWindow p,View a,int g,int x,int y){events.add(\"show\");attempts++;if(attempts==failAt)return false;p.x=x;p.y=y;p.showing=true;p.shownOrder=++order;return true;}}",
            implementation,
            "static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}",
            "public static void run(){Context c=new Context();FrameLayout root=new FrameLayout(),body=new FrameLayout();NotebookWorkspace ws=new NotebookWorkspace();NotebookWorkspace.Pane pane=ws.add(7,NotebookWorkspace.Position.FLOATING);ws.setFloatingBase(true);int[] clicks={0,0,0,0};NotebookWindowControls.Listener listener=new NotebookWindowControls.Listener(){public void menu(){clicks[0]++;}public void minimize(){clicks[1]++;}};NotebookEditorCorners controls=new NotebookEditorCorners(c,root,body,ws,pane,listener,()->events.add(\"clip\"),forward->{if(forward)clicks[3]++;else clicks[2]++;});",
            "long noteOrder=++order;controls.name(\"Note\");controls.position(100,200,600,800,true,false);check(events.equals(Arrays.asList(\"clip\",\"show\",\"show\")),\"native exclusion is installed before the corner windows appear\");check(controls.left.layer==1002&&controls.right.layer==1002&&controls.left.shownOrder>noteOrder&&controls.right.shownOrder>noteOrder,\"both controls are separate windows above the AI-main floating editor\");check(controls.left.content==controls.controls.menu&&controls.right.content==controls.controls.minimize,\"the actual shared gesture controls own the overlay windows\");check(controls.left.x==107&&controls.left.y==971&&controls.right.x==671&&controls.right.y==971&&controls.left.width==22&&controls.right.width==22,\"the two small controls sit inside opposite bottom corners\");controls.left.content.performClick();controls.right.content.performClick();check(clicks[0]==1&&clicks[1]==1,\"tapping visible corner windows routes to options and minimize\");",
            "controls.history(true,true);controls.position(100,200,600,800,true,false);check(controls.navigation.showing&&controls.navigation.x==619&&controls.navigation.width==48&&controls.bounds().size()==3,\"history arrows are also in a separate window to the left of minimize\");controls.back.performClick();controls.forward.performClick();check(clicks[2]==1&&clicks[3]==1,\"history actions retain their routing\");",
            "long earlier=controls.left.shownOrder;noteOrder=++order;controls.position(110,220,500,500,true,true);check(controls.left.shownOrder>noteOrder&&controls.left.shownOrder>earlier&&controls.right.x==581&&controls.right.y==691,\"raising or resizing the note puts both controls back above the new surface and follows its bounds\");check(controls.bounds().get(0).left==117,\"the native exclusion follows the moved control\");",
            "controls.history(false,false);controls.position(110,220,500,500,false,false);check(controls.left.layer==1000&&controls.right.layer==1000&&!controls.navigation.showing&&controls.bounds().size()==2,\"ordinary floating notes use their own panel layer and remove unused history\");controls.hide();check(!controls.left.showing&&!controls.right.showing&&controls.bounds().isEmpty(),\"hiding the note removes windows and native exclusions\");",
            "NotebookPopupHost.failAt=NotebookPopupHost.attempts+1;controls.position(10,10,500,500,true,false);check(!controls.left.showing&&controls.right.showing&&controls.bounds().size()==1,\"a failed window attachment leaves no invisible native exclusion and keeps the other control\");NotebookPopupHost.failAt=0;controls.position(10,10,500,500,true,false);check(controls.left.showing&&controls.bounds().size()==2,\"a failed corner can reopen on a later layout\");controls.hide();",
            "System.out.println(\"NotebookEditorCorners: \"+checks+\" assertions passed (production windows, simulated native-surface ordering, touch routing, movement and exclusions; not tablet verification).\");}",
            "}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.EditorCornersFixture", fixture);
        companionPresentation();
        selectionActions();
    }

    private static void companionPresentation() throws Exception {
        String source = new String(Files.readAllBytes(Paths.get(
            "app/src/main/java/org/eink/inkprobe/notebook/NotebookCompanion.java")), StandardCharsets.UTF_8);
        String position = NotebookWorkspaceActivationTest.method(source, "\n    void position() {")
            .replace("android.view.WindowManager.LayoutParams", "WindowManager.LayoutParams");
        String fixture = String.join("\n",
            "package org.eink.inkprobe.notebook;public class CompanionPresentationFixture {",
            "static long order;static class WindowManager{static class LayoutParams{static final int TYPE_APPLICATION_PANEL=1000,TYPE_APPLICATION_SUB_PANEL=1002;}}static class Gravity{static final int TOP=48,LEFT=3;}",
            "static class View{static final int VISIBLE=0,GONE=8;ViewGroup parent;int visibility;Object layout;ViewGroup getParent(){return parent;}void setVisibility(int n){visibility=n;}void setContentDescription(String s){}Object getLayoutParams(){return layout;}void setLayoutParams(Object x){layout=x;}}",
            "static class ViewGroup extends View{void removeView(View v){v.parent=null;}}static class FrameLayout extends ViewGroup{int width=1000,height=1200;boolean attached=true;boolean isAttachedToWindow(){return attached;}int getWidth(){return width;}int getHeight(){return height;}void getLocationOnScreen(int[] p){p[0]=20;p[1]=30;}void addView(View v,int index,LayoutParams p){v.parent=this;v.layout=p;}void addView(View v){v.parent=this;v.layout=new LayoutParams(0,0);}static class LayoutParams{int width,height,leftMargin,topMargin;LayoutParams(int w,int h){width=w;height=h;}}}",
            "static class Reader extends View{void bringToFront(){}void open(){}}static class PopupWindow{boolean showing;int layer;long shownOrder;boolean isShowing(){return showing;}void dismiss(){showing=false;}void setWindowLayoutType(int n){layer=n;}void setWidth(int n){}void setHeight(int n){}void update(int x,int y,int w,int h){}}static class NotebookPopupHost{static boolean fail;static boolean show(PopupWindow p,View root,int g,int x,int y){if(fail)return false;p.showing=true;p.shownOrder=++order;return true;}}",
            "static class Corners{boolean showing,subPanel,lastRaise;int x,y,width,height,hides;long shownOrder;void name(String n){}void history(boolean b,boolean f){}void hide(){showing=false;hides++;}void position(int x,int y,int w,int h,boolean sub,boolean raise){this.x=x;this.y=y;width=w;height=h;subPanel=sub;lastRaise=raise;if(!showing||raise){showing=true;shownOrder=++order;}}}",
            "static class Listener{int raises,changes;void raised(){raises++;}void boundsChanged(){changes++;}}",
            "final NotebookWorkspace workspace=new NotebookWorkspace();final NotebookWorkspace.Pane pane;final FrameLayout root=new FrameLayout(),body=new FrameLayout(),content=new FrameLayout();final Reader reader=new Reader();final View menu=new View(),minimize=new View(),history=new View();final PopupWindow popup=new PopupWindow();final Corners editorCorners=new Corners();final Listener listener=new Listener();boolean editor,editorPrepared,editorCornersVisible,historyBackAvailable,historyForwardAvailable,visible;int popupLayer=-1;",
            "CompanionPresentationFixture(boolean ai,boolean secondary){workspace.add(1,NotebookWorkspace.Position.FLOATING);pane=secondary?workspace.add(2,NotebookWorkspace.Position.FLOATING):workspace.base();workspace.setFloatingBase(ai);}",
            "void hide(){visible=false;editorCornersVisible=false;popup.dismiss();editorCorners.hide();}void finishResizeOutline(){}",
            NotebookWorkspaceActivationTest.method(source,"void show(String name, View writingSurface)"),position,
            NotebookWorkspaceActivationTest.method(source,"private void positionEditorCorners("),
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}",
            "public static void run(){CompanionPresentationFixture one=new CompanionPresentationFixture(true,false);one.show(\"Chosen\",new View());NotebookWorkspace.Box box=one.workspace.box(one.pane,1000,1200);check(one.editorCornersVisible&&one.popup.showing&&one.popup.layer==1002&&one.editorCorners.showing&&one.editorCorners.shownOrder>one.popup.shownOrder,\"one active AI-main floating note presents corner windows after its native-surface host\");check(one.editorCorners.x==20+box.x&&one.editorCorners.y==30+box.y&&one.editorCorners.width==box.width&&one.editorCorners.height==box.height&&one.editorCorners.subPanel,\"corner overlay follows the actual floating-note screen box\");",
            "one.pane.x=.8f;one.position();box=one.workspace.box(one.pane,1000,1200);check(one.editorCorners.x==20+box.x&&!one.editorCorners.lastRaise,\"moving an existing note updates the control window geometry\");one.popup.dismiss();one.position();check(one.editorCorners.lastRaise&&one.editorCorners.shownOrder>one.popup.shownOrder,\"re-presenting an active note also raises its controls\");",
            "one.popup.dismiss();NotebookPopupHost.fail=true;one.position();NotebookPopupHost.fail=false;check(!one.visible&&!one.editorCorners.showing,\"failure to present the note cannot leave orphaned controls\");",
            "CompanionPresentationFixture multi=new CompanionPresentationFixture(false,true);multi.show(\"Other\",null);check(!multi.editorCornersVisible&&multi.menu.visibility==View.VISIBLE&&multi.minimize.visibility==View.VISIBLE,\"an inactive floating note uses its visible embedded controls\");multi.show(\"Other\",new View());check(multi.editorCornersVisible&&multi.menu.visibility==View.GONE&&multi.editorCorners.showing&&multi.popup.layer==1000&&multi.editorCorners.shownOrder>multi.popup.shownOrder,\"when that note becomes writable, its controls move above the active native surface\");multi.show(\"Other\",null);check(!multi.editorCornersVisible&&!multi.editorCorners.showing&&multi.menu.visibility==View.VISIBLE,\"giving up editing removes the extra windows and restores embedded controls\");",
            "System.out.println(\"NotebookCompanionPresentation: \"+checks+\" assertions passed (actual note presentation, focus transitions, movement and failed attachment; synthetic WindowManager).\");}",
            "}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.CompanionPresentationFixture", fixture);
    }

    private static void selectionActions() throws Exception {
        String source = new String(Files.readAllBytes(Paths.get(
            "app/src/main/java/org/eink/inkprobe/notebook/NotebookActivity.java")), StandardCharsets.UTF_8);
        String fixture = String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;import java.io.*;public class FloatingSelectionActionsFixture {",
            "static class NotebookSelectionTools{enum Action{COPY,DUPLICATE,MOVE,CUT,DELETE,EXPORT,AI_CHAT}int notices;void copied(){notices++;}}static class NotebookLasso{enum Action{DELETE,DUPLICATE}static class Bounds{float left=10,top=20,right=40,bottom=50;}static class Selection{final List<Object> strokes=new ArrayList<>();final Bounds bounds=new Bounds();}}",
            "interface Callback{void complete(NotebookLasso.Selection s,IOException e);}static class Session{int copies,edits;NotebookLasso.Action action;float dx,dy;void copy(NotebookLasso.Selection s){copies++;}void editSelection(int page,NotebookLasso.Selection s,NotebookLasso.Action a,float x,float y,Callback cb){edits++;action=a;dx=x;dy=y;cb.complete(s,null);}}static class Viewport{int pageWidth(int id){return 200;}int pageHeight(int id){return 200;}}",
            "final Session session=new Session();final Viewport viewport=new Viewport();final NotebookSelectionTools selectionTools=new NotebookSelectionTools();NotebookLasso.Selection selection=new NotebookLasso.Selection();Object selectionOutline=new Object(),shownError;boolean ready=true;int generation=1,selectionPage=1,pauses,finishes,exports,moves,appends;List<Object> appended;boolean canEdit(){return ready;}void pauseForEdit(boolean keep){pauses++;}void finishLasso(int r,int i,NotebookLasso.Selection s,IOException e,boolean k){finishes++;}void exportSelection(){exports++;}void moveSelectionToPage(){moves++;}void appendAiSelection(Object figure,List<Object> strokes){appends++;appended=strokes;}",
            NotebookWorkspaceActivationTest.method(source,"private void performSelectionAction("),
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run(){FloatingSelectionActionsFixture f=new FloatingSelectionActionsFixture();Object ink=new Object();f.selection.strokes.add(ink);f.performSelectionAction(NotebookSelectionTools.Action.COPY);check(f.session.copies==1&&f.selectionTools.notices==1&&f.pauses==0,\"Copy routes the selected strokes to the clipboard\");f.performSelectionAction(NotebookSelectionTools.Action.AI_CHAT);check(f.appends==1&&f.appended.size()==1&&f.appended.get(0)==ink&&f.appended!=f.selection.strokes,\"AI action passes an independent list of the selected strokes to the active chat\");f.performSelectionAction(NotebookSelectionTools.Action.CUT);check(f.session.copies==2&&f.session.edits==1&&f.session.action==NotebookLasso.Action.DELETE&&f.finishes==1,\"Cut copies then removes the selected ink\");f.performSelectionAction(NotebookSelectionTools.Action.DELETE);check(f.session.edits==2&&f.session.action==NotebookLasso.Action.DELETE&&f.finishes==2,\"Delete removes the selection\");f.performSelectionAction(NotebookSelectionTools.Action.DUPLICATE);check(f.session.action==NotebookLasso.Action.DUPLICATE&&f.session.dx==24&&f.session.dy==24,\"Duplicate retains the selection placement behavior\");f.performSelectionAction(NotebookSelectionTools.Action.MOVE);f.performSelectionAction(NotebookSelectionTools.Action.EXPORT);check(f.moves==1&&f.exports==1,\"Move and export remain reachable\");f.ready=false;f.performSelectionAction(NotebookSelectionTools.Action.AI_CHAT);check(f.appends==1,\"actions are blocked while the editor is unavailable\");System.out.println(\"NotebookFloatingSelectionActions: \"+checks+\" assertions passed (copy, cut, delete, duplicate, move, export and append to AI).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.FloatingSelectionActionsFixture", fixture);
    }
}
